-- public.azul_unidades (02/11/2026) — autorizada nominalmente pelo dono (vale só
-- para esta migration: tabela, RLS e carga).
--
-- O QUE E
--   Lista das unidades da Azul Cargo por cidade, extraída da API da própria Azul
--   (Unidades/LocalizarUnidades por UF, 26 UFs sem RS, 28/10/2026): 317 unidades.
--   A cotação da Azul é para retirada em unidade, e a Azul não tem unidade em
--   toda cidade. O orçamento e o Maestro só oferecem a Azul onde há unidade
--   elegível, e só os serviços que essas unidades atendem (lib/unidades-azul.ts,
--   frete.service.ts). A recotação da Expedição e o complementar não leem.
--
-- ELEGIVEL
--   true  = unidade da própria Azul (classe AZUL) e, das em dúvida, TLZ01
--           (Catalão/GO) e as 4 sem ECOMM (TBT, ITB, MEU, NAT): 291 linhas.
--   false = as 8 excluídas (transportadora parceira, ponto dentro de cliente,
--           estrutura interna, só corporativo), os pontos de venda (bases PV e
--           terminadas em PV), LFR02, BNU02, QPA02, SAO23 e PPBST: 26 linhas.
--   As 317 ficam guardadas: a lista muda só trocando o flag.
--
-- CHAVE DA CIDADE
--   cidade_chave = mesma expressão de ibge_municipios.nome_chave (sem acento,
--   minúsculas, só [a-z0-9]); a comparação no app usa UF + essa chave. As 238
--   cidades distintas existem em ibge_municipios (conferido em 02/11/2026).
--
-- ACESSO
--   RLS ligado; leitura só para authenticated; nenhuma política de escrita, então
--   o app não grava (service_role continua por BYPASSRLS). Criada por postgres, a
--   tabela não recebe grant para anon pelo default privilege; o REVOKE abaixo é
--   garantia. Conferir o ACL depois de aplicar:
--     select grantee, array_agg(privilege_type order by privilege_type)
--       from information_schema.role_table_grants
--      where table_schema = 'public' and table_name = 'azul_unidades'
--      group by grantee;
--
-- ROLLBACK —
--   drop table if exists public.azul_unidades;

create table if not exists public.azul_unidades (
  base          text primary key,
  nome          text not null,
  cidade        text not null,
  uf            text not null,
  cidade_chave  text generated always as (
                  regexp_replace(
                    lower(translate(cidade,
                      'ÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇÑáàâãäéèêëíìîïóòôõöúùûüçñ',
                      'AAAAAEEEEIIIIOOOOOUUUUCNaaaaaeeeeiiiiooooouuuucn')),
                    '[^a-z0-9]', '', 'g')
                ) stored,
  servicos      text[] not null default '{}',
  servicos_cru  text not null default '',
  classe        text not null,
  elegivel      boolean not null default false,
  motivo        text,
  extraido_em   timestamptz not null default '2026-10-28 00:00:00-03',
  constraint azul_unidades_uf_2_letras check (uf ~ '^[A-Z]{2}$'),
  constraint azul_unidades_sem_rs check (uf <> 'RS'),
  constraint azul_unidades_classe check (classe in ('AZUL', 'DUVIDA', 'EXCLUIDA')),
  constraint azul_unidades_servicos_canonicos check (servicos <@ array['ECOMM', 'EXPRESSO', 'PREMIUM', 'STANDARD']::text[])
);

comment on table public.azul_unidades is
  'Unidades da Azul Cargo por cidade (API LocalizarUnidades, 28/10/2026). elegivel = conta como ponto de retirada: o orçamento e o Maestro só cotam a Azul onde há unidade elegível e só os serviços dela. Lido por frete.service.ts (lib/unidades-azul.ts).';
comment on column public.azul_unidades.cidade_chave is 'Mesma expressão de ibge_municipios.nome_chave; comparar junto com uf.';
comment on column public.azul_unidades.elegivel is 'true = unidade da própria Azul, vale como retirada. false = parceira, ponto dentro de cliente, ponto de venda ou em dúvida.';

create index if not exists azul_unidades_uf_cidade_chave_idx
  on public.azul_unidades (uf, cidade_chave) where elegivel;

alter table public.azul_unidades enable row level security;

drop policy if exists azul_unidades_leitura_autenticado on public.azul_unidades;
create policy azul_unidades_leitura_autenticado
  on public.azul_unidades for select to authenticated using (true);

revoke all on table public.azul_unidades from anon;

on conflict (base) do update set
  nome = excluded.nome, cidade = excluded.cidade, uf = excluded.uf, servicos = excluded.servicos,
  servicos_cru = excluded.servicos_cru, classe = excluded.classe, elegivel = excluded.elegivel, motivo = excluded.motivo;
